$('#yr').textContent=new Date().getFullYear();

/* ---------- estado global ---------- */
const S={mx:.5,my:.5,tmx:.5,tmy:.5,pmx:.5,pmy:.5,mvel:0,scroll:0,beat:0,state:0,tstate:0,
  t:0,frame:0,fps:60,fpsAcc:0,fpsN:0,dpr:Math.min(devicePixelRatio||1,1.5),running:true,booted:false};

/* ============================================================
   [A] BOOT SEQUENCE
   ============================================================ */
const bootLines=[
  "> mounting /dev/consciousness ......... <span class='ok'>OK</span>",
  "> loading priors [bayes.core] ......... <span class='ok'>OK</span>",
