  "> impact: INEVITABLE"
];
const bootLog=$('#boot-log'), bootFill=$('#boot-fill'), bootPct=$('#boot-pct');
let bi=0, bp=0;
function bootTick(){
  if(S.booted) return;
  bp=Math.min(100, bp+rand(3,11));
  bootFill.style.width=bp+'%'; bootPct.textContent=Math.floor(bp)+'%';
  if(bi<bootLines.length && bp> (bi+1)/bootLines.length*100){
    const d=document.createElement('div'); d.innerHTML=bootLines[bi++]; bootLog.appendChild(d);
    while(bootLog.children.length>6) bootLog.removeChild(bootLog.firstChild);
  }
  if(bp>=100){ finishBoot(); return; }
  setTimeout(bootTick, rand(90,220));
}
function finishBoot(){
