TRIRICA EL CODIGO AUMENTA EL VISUAL Y SU REACCION A CADA F5 SE POTENCIALIZA <!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/>
<meta name="theme-color" content="#040406"/>
<meta name="color-scheme" content="dark"/>
<meta name="description" content="NOIACORE LAB — Inteligência silenciosa. Core is invisible. Impact is inevitable."/>
<meta property="og:title" content="NOIACORE — LAB"/>
<meta property="og:description" content="Arquitetura de inteligência. Core is invisible. Impact is inevitable."/>
<title>NOIACORE — LAB</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' fill='%23040406'/%3E%3Cpath d='M8 24 L16 6 L24 24' fill='none' stroke='%23fff' stroke-width='2'/%3E%3Ccircle cx='16' cy='16' r='13' fill='none' stroke='%237d9bff' stroke-opacity='.5'/%3E%3C/svg%3E"/>
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400&family=Space+Grotesk:wght@300;400;500&display=swap" rel="stylesheet"/>
<style>
/* ============================================================
   NOIACORE / LAB · v3 — INSTRUMENTO
   [00] tokens · [01] reset · [02] fondo/capas · [03] cursor
   [04] boot · [05] topbar/HUD · [06] hero · [07] marquee
   [08] bloques · [09] manifesto · [10] arquitetura · [11] signal
   [12] limites · [13] telemetry · [14] terminal · [15] axiomas
   [16] footer · [17] reveal/motion
   ============================================================ */

/* [00] TOKENS ------------------------------------------------ */
:root{
  --bg:#040406; --bg2:#07070b;
  --ink:238,238,242;
  --mute:rgba(var(--ink),.56); --faint:rgba(var(--ink),.32);
  --ghost:rgba(var(--ink),.16); --line:rgba(var(--ink),.10); --line2:rgba(var(--ink),.26);
  --acc:125,155,255; --acc2:180,200,255; --warm:255,158,90;
  --f-d:"Space Grotesk",system-ui,sans-serif;
  --f-b:"Inter",system-ui,sans-serif;
  --f-m:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  --txl:.6em; --tlg:.4em; --tmd:.26em; --tsm:.16em;
  --ease:cubic-bezier(.16,1,.3,1);
  --maxw:1320px;
  --scroll:0; --mx:.5; --my:.5; --beat:0; --state:0;
}

/* [01] RESET ------------------------------------------------- */
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:rgba(var(--ink),.88);font-family:var(--f-b);
  font-weight:300;line-height:1.6;overflow-x:hidden;-webkit-font-smoothing:antialiased;cursor:none}
body.locked{overflow:hidden}
::selection{background:rgba(var(--acc),.35);color:#fff}
::-webkit-scrollbar{width:9px}
::-webkit-scrollbar-track{background:#040406}
::-webkit-scrollbar-thumb{background:rgba(var(--ink),.14);border:2px solid #040406;border-radius:9px}
::-webkit-scrollbar-thumb:hover{background:rgba(var(--acc),.4)}
a{color:inherit}
:focus-visible{outline:1px solid rgba(var(--acc),.8);outline-offset:3px}

/* [02] FONDO / CAPAS ---------------------------------------- */
#gl,#fx{position:fixed;inset:0;width:100%;height:100%;display:block}
#gl{z-index:0}
#fx{z-index:1;pointer-events:none}
body.no-webgl #gl{display:none}
body.no-webgl .fb{display:block}
.fb{display:none;position:fixed;inset:0;z-index:0;
  background:conic-gradient(from 0deg at 50% 44%,transparent 0 40%,rgba(var(--acc),.10) 50%,transparent 60% 100%),
  radial-gradient(58% 48% at 50% 44%,rgba(var(--acc),.10),transparent 70%),var(--bg);
  animation:fbspin 26s linear infinite}
@keyframes fbspin{to{transform:rotate(360deg) scale(1.06)}}
.vignette{position:fixed;inset:0;z-index:2;pointer-events:none;
  background:radial-gradient(125% 95% at 50% 42%,transparent 46%,rgba(0,0,0,.82) 100%)}
.grain{position:fixed;inset:-100%;z-index:3;pointer-events:none;opacity:.055;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  animation:grain 1.1s steps(4) infinite}
@keyframes grain{0%{transform:translate(0,0)}25%{transform:translate(-4%,3%)}50%{transform:translate(3%,-2%)}75%{transform:translate(-2%,-3%)}100%{transform:translate(2%,2%)}}
.scan{position:fixed;left:0;right:0;height:160px;z-index:3;pointer-events:none;mix-blend-mode:screen;
  background:linear-gradient(to bottom,transparent,rgba(var(--acc),.05),transparent);animation:scan 8s linear infinite}
@keyframes scan{0%{top:-160px}100%{top:100%}}
.progress{position:fixed;top:0;left:0;height:2px;width:0;z-index:90;
  background:linear-gradient(90deg,rgba(var(--acc),.9),#fff);box-shadow:0 0 12px rgba(var(--acc),.7)}

/* [03] CURSOR ----------------------------------------------- */
.c-ring,.c-dot{position:fixed;top:0;left:0;z-index:140;pointer-events:none;border-radius:50%;
  transform:translate(-50%,-50%);will-change:transform}
.c-ring{width:38px;height:38px;border:1px solid rgba(var(--ink),.32);
  transition:width .35s var(--ease),height .35s var(--ease),border-color .35s,background .35s}
.c-dot{width:4px;height:4px;background:#fff;box-shadow:0 0 12px rgba(var(--acc),.9)}
.c-ring.hot{width:74px;height:74px;border-color:rgba(var(--acc),.75);background:rgba(var(--acc),.05)}
.c-coords{position:fixed;z-index:140;pointer-events:none;font-family:var(--f-m);font-size:9px;
  letter-spacing:.12em;color:var(--faint);transform:translate(14px,14px);white-space:nowrap}
@media(hover:none),(pointer:coarse){body{cursor:auto}.c-ring,.c-dot,.c-coords{display:none}}

/* [04] BOOT ------------------------------------------------- */
#boot{position:fixed;inset:0;z-index:200;background:var(--bg);display:grid;place-items:center;
  transition:opacity .9s var(--ease),visibility .9s}
#boot.done{opacity:0;visibility:hidden}
.boot-in{width:min(88vw,420px);text-align:center}
.boot-logo{font-family:var(--f-d);font-size:56px;line-height:1;color:#fff;margin-bottom:26px;
  text-shadow:0 0 30px rgba(var(--acc),.5);animation:bootpulse 2.4s var(--ease) infinite}
@keyframes bootpulse{0%,100%{opacity:.6;transform:scale(.97)}50%{opacity:1;transform:scale(1.03)}}
.boot-bar{height:1px;background:var(--line);position:relative;overflow:hidden;margin:0 auto 18px}
.boot-bar i{position:absolute;left:0;top:0;height:100%;width:0;background:linear-gradient(90deg,rgba(var(--acc),.9),#fff);
  box-shadow:0 0 10px rgba(var(--acc),.8)}
.boot-meta{display:flex;justify-content:space-between;font-family:var(--f-m);font-size:10px;
  letter-spacing:.14em;color:var(--faint);text-transform:uppercase;margin-bottom:22px}
.boot-log{font-family:var(--f-m);font-size:10px;line-height:2;letter-spacing:.08em;color:var(--faint);
  text-align:left;height:120px;overflow:hidden;text-transform:uppercase}
.boot-log .ok{color:rgba(var(--acc),.85)}
.boot-skip{margin-top:20px;font-family:var(--f-m);font-size:9px;letter-spacing:.2em;color:var(--ghost);
  background:none;border:1px solid var(--line);padding:8px 16px;cursor:pointer;text-transform:uppercase;transition:.3s}
.boot-skip:hover{color:#fff;border-color:var(--line2)}

/* [05] TOPBAR / HUD ----------------------------------------- */
.topbar{position:fixed;top:0;left:0;right:0;z-index:80;display:flex;align-items:center;
  justify-content:space-between;padding:18px clamp(16px,4vw,44px);mix-blend-mode:difference}
.brand{font-family:var(--f-d);font-size:13px;letter-spacing:var(--tmd);text-transform:uppercase;
  display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none}
.brand .pulse{width:7px;height:7px;border-radius:50%;background:#fff;animation:ping 2.4s var(--ease) infinite}
@keyframes ping{0%{box-shadow:0 0 0 0 rgba(var(--acc),.6)}70%{box-shadow:0 0 0 12px rgba(var(--acc),0)}100%{box-shadow:0 0 0 0 rgba(var(--acc),0)}}
.nav{display:flex;gap:clamp(12px,2vw,26px)}
.nav a{font-family:var(--f-d);font-size:10px;letter-spacing:var(--tsm);text-transform:uppercase;
  color:var(--mute);text-decoration:none;position:relative;padding:4px 0;transition:color .3s}
.nav a::after{content:"";position:absolute;left:0;bottom:0;width:0;height:1px;background:#fff;transition:width .4s var(--ease)}
.nav a:hover,.nav a.active{color:#fff}
.nav a.active::after,.nav a:hover::after{width:100%}
.tools{display:flex;gap:10px}
.tbtn{font-family:var(--f-m);font-size:9px;letter-spacing:.14em;color:var(--mute);background:none;
  border:1px solid var(--line);padding:6px 10px;cursor:pointer;text-transform:uppercase;transition:.3s}
.tbtn:hover,.tbtn.on{color:#fff;border-color:rgba(var(--acc),.6);background:rgba(var(--acc),.06)}
@media(max-width:860px){.nav{display:none}}

/* HUD lateral */
.hud-side{position:fixed;right:clamp(10px,2vw,26px);top:50%;transform:translateY(-50%);z-index:70;
  display:flex;flex-direction:column;gap:14px;align-items:flex-end;pointer-events:none}
.hud-card{border:1px solid var(--line);background:rgba(4,4,6,.5);backdrop-filter:blur(6px);
  padding:10px 12px;font-family:var(--f-m);font-size:9px;letter-spacing:.1em;color:var(--faint);
  text-transform:uppercase;min-width:132px}
.hud-card .k{color:var(--ghost)}
.hud-card .v{color:var(--mute);float:right}
.hud-card .v.live{color:rgba(var(--acc),.9)}
.spark{width:108px;height:26px;display:block;margin-top:6px}
.radar{width:96px;height:96px}
.radar .sweep{transform-origin:50% 50%;animation:spin 4s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.radar .blip{animation:blip 4s ease-out infinite}
@keyframes blip{0%,70%{opacity:0}75%{opacity:1}100%{opacity:0}}
@media(max-width:1100px){.hud-side{display:none}}

/* [06] HERO ------------------------------------------------- */
.hero{position:relative;z-index:4;min-height:100svh;display:flex;flex-direction:column;
  align-items:center;justify-content:center;padding:90px 16px 40px;overflow:hidden}
.hud{position:absolute;inset:clamp(60px,9vh,100px) clamp(16px,4vw,44px);z-index:5;pointer-events:none}
.hud .brk{position:absolute;width:26px;height:26px;border:1px solid var(--line2)}
.hud .tl{top:0;left:0;border-right:0;border-bottom:0}.hud .tr{top:0;right:0;border-left:0;border-bottom:0}
.hud .bl{bottom:0;left:0;border-right:0;border-top:0}.hud .br{bottom:0;right:0;border-left:0;border-top:0}
.hud .tel{position:absolute;font-family:var(--f-m);font-size:9px;letter-spacing:.12em;color:var(--faint);
  text-transform:uppercase;line-height:2}
.hud .tel.tl{top:34px;left:0}.hud .tel.tr{top:34px;right:0;text-align:right}
.hud .tel.bl{bottom:0;left:0}.hud .tel.br{bottom:0;right:0;text-align:right}
.hud .tel b{color:var(--mute);font-weight:400}
.hud .tel .live{color:rgba(var(--acc),.9)}
.crosshair{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);z-index:5;pointer-events:none;opacity:.5}
.crosshair::before,.crosshair::after{content:"";position:absolute;background:var(--line2)}
.crosshair::before{width:1px;height:22px;left:0;top:-11px}
.crosshair::after{width:22px;height:1px;left:-11px;top:0}
@media(max-width:640px){.hud .tel.tr,.hud .tel.bl{display:none}}

.corner{position:absolute;top:clamp(70px,10vh,110px);z-index:6;max-width:220px}
.corner p{margin:0;font-family:var(--f-d);font-weight:300;font-size:11px;line-height:2.1;
  letter-spacing:var(--tsm);text-transform:uppercase;color:var(--faint)}
.corner .ln{display:block;overflow:hidden}
.corner .ln i{display:block;font-style:normal;transform:translateY(110%);animation:rise .9s var(--ease) forwards}
.corner.left{left:clamp(16px,5vw,72px)}.corner.right{right:clamp(16px,5vw,72px);text-align:right}
.corner .dash{display:block;width:22px;height:1px;background:var(--line2);margin-top:14px;opacity:0;animation:fade 1s 1.2s forwards}
.corner.right .dash{margin-left:auto}
@keyframes rise{to{transform:translateY(0)}}
@keyframes fade{to{opacity:1}}
@media(max-width:860px){.corner{display:none}}

.wordmark{position:absolute;z-index:7;left:50%;top:60%;transform:translate(-50%,-50%);
  display:flex;align-items:center;gap:clamp(7px,1.6vw,17px);font-family:var(--f-d);font-weight:300;
  font-size:clamp(30px,8vw,84px);line-height:1;color:#fff;white-space:nowrap}
.wordmark .ch{display:inline-block;overflow:hidden}
.wordmark .ch i{display:inline-block;font-style:normal;transform:translateY(115%);
  animation:rise 1s var(--ease) forwards;animation-delay:calc(.5s + var(--i)*.06s)}
.wordmark .lambda{height:.9em;width:auto;transform:translateY(.05em)}
.wordmark .lambda path{stroke:#fff;stroke-dasharray:60;stroke-dashoffset:60;animation:draw 1.1s var(--ease) forwards;animation-delay:.9s}
@keyframes draw{to{stroke-dashoffset:0}}
.wordmark::after{content:"";position:absolute;inset:-10% -2%;z-index:2;pointer-events:none;
  background:linear-gradient(105deg,transparent 38%,rgba(255,255,255,.55) 50%,transparent 62%);
  mix-blend-mode:overlay;transform:translateX(-130%);animation:shimmer 6s 2.2s ease-in-out infinite}
@keyframes shimmer{0%{transform:translateX(-130%)}30%,100%{transform:translateX(130%)}}
.sub-lab{position:absolute;z-index:7;left:50%;top:69%;transform:translate(-50%,-50%);
  font-family:var(--f-d);font-size:clamp(11px,1.7vw,16px);letter-spacing:var(--txl);color:var(--mute);opacity:0;animation:fade 1s 1.5s forwards}
.state-tag{position:absolute;z-index:7;left:50%;top:74.5%;transform:translateX(-50%);
  font-family:var(--f-m);font-size:9px;letter-spacing:.3em;color:rgba(var(--acc),.7);text-transform:uppercase;opacity:0;animation:fade 1s 1.7s forwards}
.axis-b{position:absolute;z-index:7;left:50%;top:80%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center;opacity:0;animation:fade 1s 1.8s forwards}
.tagline{font-family:var(--f-d);font-size:clamp(9px,1.2vw,12px);letter-spacing:var(--tmd);text-transform:uppercase;color:var(--faint);line-height:2.3}
.orb-foot{width:16px;height:16px;border-radius:50%;border:1px solid rgba(var(--ink),.5);
  box-shadow:0 0 22px rgba(var(--acc),.5),inset 0 0 8px rgba(var(--acc),.3);animation:foot 2.4s var(--ease) infinite}
@keyframes foot{0%,100%{transform:scale(.85);opacity:.5}50%{transform:scale(1.15);opacity:1}}
.scrollcue{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);z-index:7;
  font-family:var(--f-m);font-size:8px;letter-spacing:.3em;color:var(--ghost);display:flex;flex-direction:column;align-items:center;gap:8px;opacity:0;animation:fade 1s 2s forwards}
.scrollcue .bar{width:1px;height:30px;background:linear-gradient(var(--faint),transparent);animation:cue 2s var(--ease) infinite}
@keyframes cue{0%{transform:scaleY(.2);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}51%{transform-origin:bottom}100%{transform:scaleY(.2);transform-origin:bottom}}

/* [07] MARQUEE ---------------------------------------------- */
.marquee{position:relative;z-index:4;border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  overflow:hidden;padding:13px 0;background:rgba(0,0,0,.35);backdrop-filter:blur(2px)}
.marquee .track{display:flex;gap:46px;width:max-content;animation:mq 34s linear infinite;
  font-family:var(--f-d);font-size:11px;letter-spacing:var(--tmd);text-transform:uppercase;color:var(--faint)}
.marquee .track span{display:flex;align-items:center;gap:46px}
.marquee em{font-style:normal;color:rgba(var(--acc),.75)}
.marquee .dot{width:4px;height:4px;border-radius:50%;background:var(--line2)}
@keyframes mq{to{transform:translateX(-50%)}}

/* [08] BLOQUES ---------------------------------------------- */
section.block{position:relative;z-index:4;padding:clamp(88px,13vh,160px) 0}
.wrap{width:min(92vw,var(--maxw));margin-inline:auto}
.idx{font-family:var(--f-m);font-size:11px;letter-spacing:var(--tmd);color:var(--faint);
  display:flex;align-items:center;gap:14px;margin-bottom:36px;text-transform:uppercase}
.idx::after{content:"";flex:1;height:1px;background:var(--line)}
.idx .blink{width:6px;height:6px;border-radius:50%;background:rgba(var(--acc),.8);animation:blink 1.4s steps(1) infinite}
@keyframes blink{50%{opacity:.15}}

/* [09] MANIFESTO -------------------------------------------- */
.manifesto h2{font-family:var(--f-d);font-weight:300;font-size:clamp(28px,6vw,70px);line-height:1.1;
  margin:0 0 30px;color:rgba(var(--ink),.96);max-width:17ch}
.manifesto h2 em{font-style:normal;color:var(--mute)}
.manifesto .lead{max-width:64ch;color:var(--mute);font-size:clamp(14px,1.5vw,18px);line-height:1.9}
.manifesto .lead .hl{color:rgba(var(--ink),.94);background:linear-gradient(transparent 60%,rgba(var(--acc),.18) 60%)}
.decode{font-variant-ligatures:none}

/* [10] ARQUITETURA ------------------------------------------ */
.grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-left:1px solid var(--line)}
.cell{position:relative;border-right:1px solid var(--line);border-bottom:1px solid var(--line);
  padding:32px 24px 46px;min-height:230px;display:flex;flex-direction:column;gap:13px;overflow:hidden;transition:background .5s var(--ease)}
.cell::before{content:"";position:absolute;inset:0;opacity:0;transition:opacity .5s;
  background:radial-gradient(120% 80% at 50% 0%,rgba(var(--acc),.10),transparent 70%)}
.cell:hover::before{opacity:1}.cell:hover{background:rgba(var(--ink),.02)}
.cell .n{font-family:var(--f-m);font-size:10px;letter-spacing:var(--tmd);color:var(--faint)}
.cell h3{margin:0;font-family:var(--f-d);font-weight:400;font-size:clamp(15px,1.6vw,19px);letter-spacing:var(--tsm);text-transform:uppercase;color:rgba(var(--ink),.94)}
.cell p{margin:0;color:var(--faint);font-size:13px;line-height:1.8}
.cell .glyph{position:absolute;right:18px;bottom:16px;width:34px;height:34px;opacity:.4;transition:opacity .5s,transform .6s var(--ease)}
.cell:hover .glyph{opacity:.9;transform:rotate(90deg)}
.cell .glyph *{transition:stroke .5s}
.cell:hover .glyph *{stroke:rgba(var(--acc2),.9)}
@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:520px){.grid{grid-template-columns:1fr}}

/* [11] SIGNAL ----------------------------------------------- */
.signal-wrap{display:grid;grid-template-columns:1.1fr .55fr .75fr;border:1px solid var(--line)}
.panel{position:relative;min-height:340px;overflow:hidden;background:rgba(0,0,0,.35)}
.panel+.panel{border-left:1px solid var(--line)}
.panel canvas{position:absolute;inset:0;width:100%;height:100%}
.panel .lab{position:absolute;top:12px;left:14px;font-family:var(--f-m);font-size:9px;letter-spacing:var(--tmd);color:var(--faint);text-transform:uppercase;z-index:2}
.panel .lab.r{left:auto;right:14px;color:rgba(var(--acc),.75)}
.corezone{background:radial-gradient(340px 340px at var(--cx,50%) var(--cy,50%),rgba(var(--acc),.12),transparent 62%)}
.corezone .glyph{position:absolute;inset:0;display:grid;place-items:center;
  -webkit-mask:radial-gradient(150px 150px at var(--cx,50%) var(--cy,50%),#000,transparent 72%);
          mask:radial-gradient(150px 150px at var(--cx,50%) var(--cy,50%),#000,transparent 72%)}
.corezone .glyph svg{width:min(60%,260px);height:auto}
.corezone .glyph svg *{stroke:rgba(var(--ink),.85)}
.corezone .prompt{position:relative;z-index:2;text-align:center;pointer-events:none;
  font-family:var(--f-d);font-size:clamp(12px,1.6vw,17px);letter-spacing:var(--tlg);text-transform:uppercase;color:var(--ghost)}
.corezone .prompt small{display:block;margin-top:12px;font-size:9px;letter-spacing:var(--tmd);color:var(--faint);font-family:var(--f-m)}
@media(max-width:900px){.signal-wrap{grid-template-columns:1fr}.panel+.panel{border-left:0;border-top:1px solid var(--line)}}

/* [12] LIMITES ---------------------------------------------- */
.limits{display:flex;flex-direction:column}
.limit{display:grid;grid-template-columns:120px 1fr auto;gap:clamp(18px,4vw,60px);align-items:center;
  padding:clamp(28px,5vh,54px) 0;border-top:1px solid var(--line);position:relative}
.limit:last-child{border-bottom:1px solid var(--line)}
.limit .no{font-family:var(--f-d);font-weight:300;font-size:clamp(34px,6vw,72px);line-height:1;
  color:transparent;-webkit-text-stroke:1px rgba(var(--ink),.28);transition:.5s}
.limit:hover .no{-webkit-text-stroke:1px rgba(var(--acc),.7);color:rgba(var(--acc),.06)}
.limit h3{margin:0 0 8px;font-family:var(--f-d);font-weight:400;font-size:clamp(18px,2.6vw,30px);
  letter-spacing:.02em;text-transform:uppercase;color:rgba(var(--ink),.94)}
.limit .fen{font-family:var(--f-m);font-size:10px;letter-spacing:var(--tmd);color:rgba(var(--acc),.7);text-transform:uppercase;margin-bottom:10px;display:block}
.limit p{margin:0;color:var(--mute);font-size:clamp(13px,1.4vw,16px);line-height:1.8;max-width:60ch}
.limit .viz{width:70px;height:70px;opacity:.5;transition:.5s}
.limit:hover .viz{opacity:1;transform:rotate(45deg)}
.limit .viz *{stroke:rgba(var(--ink),.6)}
@media(max-width:760px){.limit{grid-template-columns:1fr}.limit .viz{display:none}}

/* [13] TELEMETRY -------------------------------------------- */
.dash{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
.stat{background:var(--bg);padding:24px 22px;position:relative;overflow:hidden}
.stat .k{font-family:var(--f-m);font-size:9px;letter-spacing:var(--tmd);color:var(--faint);text-transform:uppercase}
.stat .num{font-family:var(--f-d);font-weight:300;font-size:clamp(28px,4vw,46px);line-height:1.1;color:rgba(var(--ink),.95);margin:8px 0 2px}
.stat .num small{font-size:.4em;color:var(--mute);letter-spacing:.1em}
.stat .spark{width:100%;height:30px;margin-top:8px}
.gauges{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-top:0}
.gauge{background:var(--bg);padding:22px;display:flex;flex-direction:column;align-items:center;gap:10px}
.gauge svg{width:78px;height:78px;transform:rotate(-90deg)}
.gauge .bg{fill:none;stroke:rgba(var(--ink),.10);stroke-width:3}
.gauge .fg{fill:none;stroke:rgba(var(--acc),.85);stroke-width:3;stroke-linecap:round;stroke-dasharray:163;stroke-dashoffset:163;transition:stroke-dashoffset .6s var(--ease);filter:drop-shadow(0 0 5px rgba(var(--acc),.6))}
.gauge .gl{font-family:var(--f-m);font-size:9px;letter-spacing:var(--tmd);color:var(--faint);text-transform:uppercase;text-align:center}
.gauge .gv{font-family:var(--f-d);font-size:15px;color:rgba(var(--ink),.9)}
@media(max-width:900px){.dash{grid-template-columns:repeat(2,1fr)}.gauges{grid-template-columns:repeat(3,1fr)}}
@media(max-width:560px){.gauges{grid-template-columns:1fr}}

/* [14] TERMINAL --------------------------------------------- */
.term{border:1px solid var(--line);background:rgba(2,2,4,.72);backdrop-filter:blur(4px);font-family:var(--f-m)}
.term-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);
  font-size:9px;letter-spacing:var(--tmd);color:var(--faint);text-transform:uppercase}
.term-bar .dots{display:flex;gap:6px;margin-right:6px}
.term-bar .dots i{width:8px;height:8px;border-radius:50%;background:var(--line2)}
.term-bar .dots i:first-child{background:rgba(var(--warm),.6)}
.term-log{padding:18px;height:300px;overflow-y:auto;font-size:12px;line-height:1.9;letter-spacing:.03em;color:var(--mute)}
.term-log .u{color:rgba(var(--acc),.9)}
.term-log .s{color:rgba(var(--ink),.85)}
.term-log .e{color:rgba(var(--warm),.85)}
.term-log .dim{color:var(--ghost)}
.term-in{display:flex;align-items:center;gap:10px;padding:12px 14px;border-top:1px solid var(--line)}
.term-in .ps{color:rgba(var(--acc),.9);font-size:13px}
.term-in input{flex:1;background:none;border:0;outline:0;color:#fff;font-family:var(--f-m);font-size:13px;letter-spacing:.03em;caret-color:rgba(var(--acc),.9)}
.term-hint{padding:8px 14px;border-top:1px solid var(--line);font-size:9px;letter-spacing:var(--tmd);color:var(--ghost);text-transform:uppercase}

/* [15] AXIOMAS ---------------------------------------------- */
.axioms{list-style:none;margin:0;padding:0;counter-reset:a}
.axioms li{display:flex;align-items:baseline;gap:24px;padding:24px 0;border-bottom:1px solid var(--line);
  font-family:var(--f-d);font-weight:300;font-size:clamp(16px,2.6vw,30px);letter-spacing:var(--tsm);
  text-transform:uppercase;color:rgba(var(--ink),.9);transition:color .4s,padding-left .5s var(--ease),letter-spacing .5s var(--ease)}
.axioms li::before{counter-increment:a;content:"0" counter(a);font-family:var(--f-m);font-size:11px;letter-spacing:var(--tmd);color:var(--faint);min-width:36px}
.axioms li span{color:var(--mute)}
.axioms li:hover{color:#fff;padding-left:12px;letter-spacing:.05em}
.axioms li:hover::before{color:rgba(var(--acc),.9)}

/* [16] FOOTER ----------------------------------------------- */
footer{position:relative;z-index:4;padding:70px 0 46px;border-top:1px solid var(--line)}
.foot{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:40px;align-items:end}
