/* estado del core por sección (scrollytelling) */
const stateNames=['DORMANT','STIRRING','AWAKENING','ACCRETION','ACCRETION','CRITICAL','SINGULARITY','SIGNAL'];
const sections=$$('[data-state]');
function updateState(){
  const vc=innerHeight/2;let best=1e9,target=0;
  for(const s of sections){const r=s.getBoundingClientRect();
    const c=Math.abs((r.top+r.height/2)-vc);
    if(c<best){best=c;target=parseFloat(s.dataset.state);}}
  S.tstate=target;
  const idx=clamp(Math.round(target*(stateNames.length-1)),0,stateNames.length-1);
  $('#state-tag').textContent='CORE STATE · '+stateNames[idx];
}
updateState();

