/* ============================================================
   [G] DECODE TEXT (scramble → reveal)
   ============================================================ */
const GLYPHS="ΛΔΘΞΣΦΨΩ01<>/\\|·—";
function decode(el){
  const final=el.dataset.text||el.textContent; el.dataset.text=final;
  if(REDUCED){el.textContent=final;return;}
  let f=0;const total=final.length*2;
  const iv=setInterval(()=>{
    f++;let out='';
    for(let i=0;i<final.length;i++){
      if(final[i]===' '){out+=' ';continue;}
      if(i<f/2)out+=final[i];
      else out+=GLYPHS[Math.floor(Math.random()*GLYPHS.length)];
    }
    el.textContent=out;
    if(f>=total){clearInterval(iv);el.textContent=final;}
  },28);
}
const decIO=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){decode(e.target);decIO.unobserve(e.target);}}),{threshold:.5});
$$('[data-decode]').forEach(el=>decIO.observe(el));

/* ============================================================
   [H] REVEAL
   ============================================================ */
const io=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{threshold:.14});
$$('.reveal').forEach(el=>io.observe(el));

