const T={lat:$('#t-lat'),lon:$('#t-lon'),dt:$('#t-dt'),sig:$('#t-sig'),ent:$('#t-ent'),fr:$('#t-fr'),
  hz:$('#scope-hz'),fps:$('#h-fps'),thr:$('#h-thr'),up:$('#h-up'),temp:$('#h-temp'),grav:$('#h-grav'),
  ffps:$('#f-fps'),dFrames:$('#d-frames'),dInf:$('#d-inf'),dLat:$('#d-lat'),dSig:$('#d-sig'),
  g1:$('#g1'),g2:$('#g2'),g3:$('#g3'),gv1:$('#gv1'),gv2:$('#gv2'),gv3:$('#gv3')};
const t0=performance.now();
function fmtUp(ms){const s=Math.floor(ms/1000),m=Math.floor(s/60),h=Math.floor(m/60);
  return (h?String(h).padStart(2,'0')+':':'')+String(m%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function setGauge(el,vEl,val){el.style.strokeDashoffset=163*(1-val);vEl.textContent=Math.round(val*100)+'%';}
setInterval(()=>{
  const up=performance.now()-t0;
  T.lat.textContent=(Math.sin(S.t*.3)*12+38).toFixed(3);
  T.lon.textContent=(Math.cos(S.t*.27)*30-9).toFixed(3);
  T.dt.textContent=(8+Math.random()*4).toFixed(2);
  const sig=96+Math.random()*4; T.sig.textContent=sig.toFixed(1);
  T.ent.textContent=(0.08+Math.random()*.12+S.beat*.05).toFixed(2);
  T.hz.textContent=(40+S.beat*30+Math.random()*4).toFixed(2)+' Hz';
  T.fps.textContent=Math.round(S.fps);T.ffps.textContent=Math.round(S.fps);
  const thr=40+S.beat*40+Math.random()*15;T.thr.textContent=thr.toFixed(1)+' GB/s';
  T.up.textContent=fmtUp(up);
  T.temp.textContent=(2.7+S.state*9+S.beat*1.5).toFixed(1)+'K';
  T.grav.textContent=(S.state*4.2+.3).toFixed(2)+' g';
  spFps.push(S.fps);spThr.push(thr);
  // dashboard
  T.dFrames.textContent=S.frame.toLocaleString('en-US');
  const inf=12+S.beat*30+Math.random()*6;T.dInf.innerHTML=inf.toFixed(1)+'<small> k</small>';
  const lat=6+Math.random()*5;T.dLat.innerHTML=lat.toFixed(1)+'<small> ms</small>';
  T.dSig.innerHTML=sig.toFixed(1)+'<small> %</small>';
  sp1.push(S.fps);sp2.push(inf*2);sp3.push(100-lat*6);sp4.push(sig);
  setGauge(T.g1,T.gv1,.7+S.beat*.25);
  setGauge(T.g2,T.gv2,.55+S.state*.4);
  setGauge(T.g3,T.gv3,.85-S.state*.3+S.beat*.1);
},140);

/* ============================================================
   [J] TERMINAL INTERACTIVA
   ============================================================ */
const termLog=$('#term-log'),termIn=$('#term-input');
function tprint(html,cls='s'){const d=document.createElement('div');d.className=cls;d.innerHTML=html;
  termLog.appendChild(d);termLog.scrollTop=termLog.scrollHeight;}
function typeLine(html,cls,done){
  if(REDUCED){tprint(html,cls);done&&done();return;}
  const d=document.createElement('div');d.className=cls;termLog.appendChild(d);
  const tmp=document.createElement('div');tmp.innerHTML=html;const full=tmp.textContent;
  let i=0;const iv=setInterval(()=>{d.textContent=full.slice(0,++i);termLog.scrollTop=termLog.scrollHeight;
    if(i>=full.length){clearInterval(iv);d.innerHTML=html;done&&done();}},12);
}
const LIMITS_LIST=[
 '01 ATENCIONAL .... atender ≠ registrar',
 '02 ORGANIZATIVO .. um borde, dois mundos',
 '03 RIQUEZA ....... detalhe é interface',
 '04 COGNITIVO ..... saber não reescreve ver',
 '05 TEMPORAL ...... o agora é editado',
 '06 CONSCIÊNCIA ... ver sem saber (blindsight)',
 '07 INFERENCIAL ... perceber é apostar',
 '08 FENOMENAL ..... qualia é irredutível'];
const CMDS={
  help:()=>typeLine('comandos: core · status · limits · signal · scan · whoami · noiacore · clear','dim'),
  core:()=>typeLine('O núcleo é invisível. O impacto é inevitável. Estado: '+stateNames[clamp(Math.round(S.state*7),0,7)],'s'),
  status:()=>typeLine('SYSTEM NOMINAL · fps '+Math.round(S.fps)+' · signal '+T.sig.textContent+'% · core T '+T.temp.textContent,'s'),
  limits:()=>{tprint('OS OITO LIMITES DA PERCEPÇÃO:','u');LIMITS_LIST.forEach(l=>tprint('&nbsp;&nbsp;'+l,'dim'));},
  signal:()=>typeLine('SINAL ADQUIRIDO · '+T.sig.textContent+'% · portadora estável','s'),
  scan:()=>typeLine('VARREDURA COMPLETA · '+Math.floor(rand(120,400))+' nós · 0 anomalias','s'),
  whoami:()=>typeLine('OBSERVADOR · consciência nº '+Math.floor(rand(1e6,9e6))+' · viés confirmado','e'),
  noiacore:()=>{tprint('&nbsp;&nbsp;&nbsp;&nbsp;Λ','u');tprint('&nbsp;&nbsp;╱ ╲','dim');tprint('NOIACORE // arquitetura de inteligência','dim');},
  clear:()=>{termLog.innerHTML='';}
};
termIn.addEventListener('keydown',e=>{
  if(e.key!=='Enter')return;
  const v=termIn.value.trim().toLowerCase();if(!v)return;
  tprint('Λ&gt; '+v,'u');termIn.value='';
  if(CMDS[v])CMDS[v]();
  else typeLine("comando não reconhecido: '"+v+"' · digite 'help'",'e');
});
$('#term').addEventListener('click',()=>termIn.focus());
// saludo inicial
setTimeout(()=>{tprint('NOIACORE SHELL v3.0 · sessão do observador iniciada','dim');
  typeLine("digite 'help' para começar",'dim');},1200);

/* ============================================================
   [K] AUDIO — drone + latido (opcional, por gesto)
   ============================================================ */
let AC=null,master=null,audioOn=false,drone=[];
const audioBtn=$('#audio-btn');
function initAudio(){
  AC=new (window.AudioContext||window.webkitAudioContext)();
  master=AC.createGain();master.gain.value=.0;master.connect(AC.destination);
  const lp=AC.createBiquadFilter();lp.type='lowpass';lp.frequency.value=420;lp.connect(master);
  [55,110.4,164.8].forEach((f,i)=>{const o=AC.createOscillator();o.type=i?'sine':'sawtooth';
    o.frequency.value=f;o.detune.value=rand(-6,6);const g=AC.createGain();g.gain.value=i?.05:.09;
    o.connect(g);g.connect(lp);o.start();drone.push(o);});
}
function thump(){
  if(!AC||!audioOn)return;const t=AC.currentTime;
  [0,.16].forEach((off,i)=>{const o=AC.createOscillator();o.type='sine';
    o.frequency.setValueAtTime(i?52:64,t+off);o.frequency.exponentialRampToValueAtTime(38,t+off+.14);
    const g=AC.createGain();g.gain.setValueAtTime(0,t+off);
    g.gain.linearRampToValueAtTime(i?.09:.14,t+off+.02);
    g.gain.exponentialRampToValueAtTime(.0001,t+off+.22);
    o.connect(g);g.connect(master);o.start(t+off);o.stop(t+off+.24);});
}
audioBtn.addEventListener('click',()=>{
  if(!AC)initAudio();
  audioOn=!audioOn;
  if(audioOn){AC.resume();master.gain.linearRampToValueAtTime(.5,AC.currentTime+1);}
  else master.gain.linearRampToValueAtTime(0,AC.currentTime+.4);
  audioBtn.classList.toggle('on',audioOn);
  audioBtn.textContent=audioOn?'AUDIO ON':'AUDIO OFF';
  audioBtn.setAttribute('aria-pressed',audioOn);
});

/* ============================================================
   [L] PERF ADAPTATIVO + VISIBILIDAD
   ============================================================ */
let perfTimer=0;
function adaptPerf(dt){
  perfTimer+=dt;
  if(perfTimer<1.5)return; perfTimer=0;
  if(S.fps<42 && S.dpr>1){S.dpr=Math.max(1,S.dpr-.25);if(glOK)sizeGL();}
  else if(S.fps>58 && S.dpr<Math.min(devicePixelRatio||1,1.5)){S.dpr+=.25;if(glOK)sizeGL();}
}
document.addEventListener('visibilitychange',()=>{S.running=!document.hidden;
  if(S.running){last=performance.now();requestAnimationFrame(frame);}});

/* ============================================================
   [M] LOOP MAESTRO
   ============================================================ */
let last=performance.now(),beatFired=false;
function frame(now){
  if(!S.running)return;
  const dt=Math.min(.05,(now-last)/1000);last=now;
  if(!REDUCED)S.t+=dt;
  S.frame++;

  // fps
  S.fpsAcc+=dt;S.fpsN++;
  if(S.fpsAcc>=.5){S.fps=S.fpsN/S.fpsAcc;S.fpsAcc=0;S.fpsN=0;}

  // mouse velocity + lerp
  const mvx=S.tmx-S.pmx,mvy=S.tmy-S.pmy;
  S.mvel=lerp(S.mvel, clamp(Math.hypot(mvx,mvy)*40,0,1), .1);
  S.pmx=S.tmx;S.pmy=S.tmy;
  S.mx+=(S.tmx-S.mx)*.06;S.my+=(S.tmy-S.my)*.06;

  // estado del core (scrollytelling)
  S.state+=(S.tstate-S.state)*.04;
  document.documentElement.style.setProperty('--state',S.state);

  // latido (lub-dub cada 2.4s)
  const phase=(S.t%2.4)/2.4;
  S.beat=REDUCED?.5:Math.pow(1-phase,3)*(.6+.4*Math.sin(phase*Math.PI));
  if(audioOn&&phase<.05&&!beatFired){thump();beatFired=true;}
  if(phase>.5)beatFired=false;

  // render GL
  if(glOK){
    gl.viewport(0,0,glCanvas.width,glCanvas.height);
    gl.uniform2f(U.u_res,glCanvas.width,glCanvas.height);
    gl.uniform1f(U.u_time,S.t);
    gl.uniform1f(U.u_scroll,S.scroll);
    gl.uniform1f(U.u_beat,S.beat);
    gl.uniform1f(U.u_state,S.state);
    gl.uniform1f(U.u_mvel,S.mvel);
    gl.uniform2f(U.u_mouse,S.mx,1-S.my);
    gl.drawArrays(gl.TRIANGLES,0,6);
  }
  // render 2D
  if(!REDUCED){drawFX();drawScope(S.t);drawSpec(S.t);}
  T.fr.textContent=String(S.frame).padStart(6,'0');

  adaptPerf(dt);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
